        'ok': True,
        'folders': []
    }
    result = main.run(payload)
    assert result == {
        'ok': True,
        'message': 'Dry run: would play audio'
    }

@patch('main.find_program')
@patch('main.find_media')
def test_run_no_media_player(mock_find_media, mock_find_program):
    payload = {'dry_run': False}
    mock_find_program.return_value = {
        'found': False,
        'path': ''
    }
    mock_find_media.return_value = {
        'ok': True,
        'folders': [{'path': 'C:\Users\rapha\Music', 'audio_files': 1}]
    }
    with patch('subprocess.Popen') as mock_popen:
        result = main.run(payload)
        assert result == {
